        var vars = {
            MasterdataDMSPath: model.MasterdataDMSPath,
            SourceSystemId: model.SourceSystemId,
            CurrencyId: model.CurrencyId,
            NumberOfInvoices: model.NumberOfInvoices,
            NumberOfCredits: model.NumberOfCredits,
            NumberOfRemittanceAdvices: model.NumberOfRemittanceAdvices,
            NumberOfOffers: model.NumberOfOffers,
            AppId: appInfo.Id,
            OfferStates: DataGeneratorTransactions.OfferStates
        };
        var d = new Dialog({
            width: 800,
            height: 500
        });
        d.init(() => {
            loadComponent($(d.element), "ScriptRunner", (component) => {
                component.init(app, d.element, vars, functions, d);
            });
        });
